"use client";
import { useState } from "react";
import Link from "next/link";
import { usePathname } from "next/navigation";

const NAV = [
  {
    label: "Market",
    items: [
      { label: "Market Overview", href: "/data-portal" },
      { label: "Daily Summary", href: "/data-portal/daily" },
      { label: "Weekly Summary", href: "/data-portal/weekly" },
      { label: "Market Indices", href: "/data-portal/indices" },
      { label: "Sector Summary", href: "/data-portal/sectors" },
      { label: "Market Performers", href: "/data-portal/daily?view=performers" },
    ],
  },
  {
    label: "Companies",
    items: [
      { label: "Company Directory", href: "/data-portal/companies" },
      { label: "Financial Statements", href: "/data-portal/companies?tab=financials" },
      { label: "Dividends", href: "/data-portal/companies?tab=dividends" },
      { label: "Shariah Status", href: "/data-portal/companies?shariah=compliant" },
    ],
  },
  {
    label: "Tools",
    items: [
      { label: "Stock Screener", href: "/data-portal/screener" },
      { label: "Historical Data", href: "/data-portal/historical-data" },
      { label: "Data Downloads", href: "/data-portal/downloads" },
    ],
  },
  {
    label: "Information",
    items: [
      { label: "Announcements", href: "/data-portal/announcements" },
      { label: "Research Reports", href: "/data-portal/research" },
      { label: "Weekly Report", href: "/data-portal/research?type=weekly_market" },
    ],
  },
];

export default function PortalNav({ isAdmin }: { isAdmin?: boolean }) {
  const pathname = usePathname();
  const [open, setOpen] = useState<string | null>(null);
  const [mobileOpen, setMobileOpen] = useState(false);

  return (
    <nav
      className="sticky top-0 z-50 border-b"
      style={{ background: "var(--navy)", borderColor: "rgba(212,175,55,0.2)" }}
    >
      {/* Top bar */}
      <div className="max-w-screen-2xl mx-auto px-4 sm:px-6 flex items-center justify-between h-14">
        {/* Logo */}
        <Link href="/data-portal" className="flex items-center gap-2 shrink-0">
          <span className="text-xl font-bold tracking-tight" style={{ color: "var(--gold)" }}>
            Stockifyy
          </span>
          <span className="hidden sm:block text-xs px-2 py-0.5 rounded" style={{ background: "rgba(212,175,55,0.15)", color: "var(--gold)" }}>
            Data Portal
          </span>
        </Link>

        {/* Desktop nav */}
        <div className="hidden lg:flex items-center gap-1">
          {NAV.map((group) => (
            <div
              key={group.label}
              className="relative"
              onMouseEnter={() => setOpen(group.label)}
              onMouseLeave={() => setOpen(null)}
            >
              <button
                className="px-3 py-2 text-sm rounded transition-colors"
                style={{
                  color: open === group.label ? "var(--gold)" : "rgba(255,255,255,0.8)",
                  background: open === group.label ? "rgba(212,175,55,0.1)" : "transparent",
                }}
              >
                {group.label} ▾
              </button>
              {open === group.label && (
                <div
                  className="absolute top-full left-0 w-52 py-1 rounded-lg shadow-xl border mt-1"
                  style={{ background: "var(--deep-blue)", borderColor: "rgba(212,175,55,0.2)", zIndex: 100 }}
                >
                  {group.items.map((item) => (
                    <Link
                      key={item.href}
                      href={item.href}
                      className="block px-4 py-2 text-sm transition-colors"
                      style={{
                        color: pathname === item.href ? "var(--gold)" : "rgba(255,255,255,0.8)",
                        background: pathname === item.href ? "rgba(212,175,55,0.1)" : "transparent",
                      }}
                      onMouseEnter={(e) => (e.currentTarget.style.color = "var(--gold)")}
                      onMouseLeave={(e) => (e.currentTarget.style.color = pathname === item.href ? "var(--gold)" : "rgba(255,255,255,0.8)")}
                    >
                      {item.label}
                    </Link>
                  ))}
                </div>
              )}
            </div>
          ))}
          {isAdmin && (
            <Link
              href="/data-portal/admin"
              className="px-3 py-2 text-sm rounded transition-colors"
              style={{ color: "rgba(255,255,255,0.8)" }}
            >
              Admin
            </Link>
          )}
        </div>

        {/* Right side */}
        <div className="flex items-center gap-3">
          <Link
            href="/"
            className="hidden sm:block text-xs"
            style={{ color: "rgba(255,255,255,0.5)" }}
          >
            ← Main Site
          </Link>
          {/* Mobile menu button */}
          <button
            className="lg:hidden p-2 rounded"
            style={{ color: "rgba(255,255,255,0.8)" }}
            onClick={() => setMobileOpen(!mobileOpen)}
          >
            {mobileOpen ? "✕" : "☰"}
          </button>
        </div>
      </div>

      {/* Mobile menu */}
      {mobileOpen && (
        <div
          className="lg:hidden border-t py-2"
          style={{ background: "var(--deep-blue)", borderColor: "rgba(212,175,55,0.2)" }}
        >
          {NAV.map((group) => (
            <div key={group.label} className="px-4 py-2">
              <div className="text-xs font-semibold mb-1 uppercase tracking-wider" style={{ color: "var(--gold)" }}>
                {group.label}
              </div>
              {group.items.map((item) => (
                <Link
                  key={item.href}
                  href={item.href}
                  className="block py-1.5 text-sm"
                  style={{ color: "rgba(255,255,255,0.8)" }}
                  onClick={() => setMobileOpen(false)}
                >
                  {item.label}
                </Link>
              ))}
            </div>
          ))}
        </div>
      )}
    </nav>
  );
}

