import type { Metadata } from "next";
import Link from "next/link";
import { db } from "@/db";
import { dailyStockPrices, dailyIndexValues, marketDailySummaries, companyAnnouncements, researchReports, tradingCalendar } from "@/db/schema";
import { desc, eq, asc, and } from "drizzle-orm";
import { formatNumber, formatVolume, formatPct, formatChange, getWeekLabel } from "@/lib/utils";
import StatCard from "@/components/ui/StatCard";
import { format, startOfWeek } from "date-fns";

export const metadata: Metadata = { title: "Market Overview" };

async function getLatestTradingDate() {
  const [latest] = await db
    .select({ tradingDate: tradingCalendar.tradingDate })
    .from(tradingCalendar)
    .where(eq(tradingCalendar.isTrading, true))
    .orderBy(desc(tradingCalendar.tradingDate))
    .limit(1);
  return latest?.tradingDate ?? new Date().toISOString().slice(0, 10);
}

async function getDashboardData() {
  try {
    const latestDate = await getLatestTradingDate();

    const [indexData, gainers, losers, volumeLeaders, announcements, research] = await Promise.all([
      db.select().from(dailyIndexValues).where(eq(dailyIndexValues.tradingDate, latestDate)).orderBy(dailyIndexValues.indexCode),
      db.select({ symbol: dailyStockPrices.symbol, close: dailyStockPrices.close, percentageChange: dailyStockPrices.percentageChange, priceChange: dailyStockPrices.priceChange })
        .from(dailyStockPrices).where(eq(dailyStockPrices.tradingDate, latestDate)).orderBy(desc(dailyStockPrices.percentageChange)).limit(5),
      db.select({ symbol: dailyStockPrices.symbol, close: dailyStockPrices.close, percentageChange: dailyStockPrices.percentageChange, priceChange: dailyStockPrices.priceChange })
        .from(dailyStockPrices).where(eq(dailyStockPrices.tradingDate, latestDate)).orderBy(asc(dailyStockPrices.percentageChange)).limit(5),
      db.select({ symbol: dailyStockPrices.symbol, volume: dailyStockPrices.volume, close: dailyStockPrices.close })
        .from(dailyStockPrices).where(eq(dailyStockPrices.tradingDate, latestDate)).orderBy(desc(dailyStockPrices.volume)).limit(5),
      db.select().from(companyAnnouncements).where(eq(companyAnnouncements.isPublic, true)).orderBy(desc(companyAnnouncements.announcementDate)).limit(5),
      db.select().from(researchReports).where(eq(researchReports.isPublic, true)).orderBy(desc(researchReports.publicationDate)).limit(3),
    ]);

    return { latestDate, indexData, gainers, losers, volumeLeaders, announcements, research };
  } catch {
    return null;
  }
}

export default async function DataPortalPage() {
  const data = await getDashboardData();
  const now = new Date();
  const weekStart = format(startOfWeek(now, { weekStartsOn: 1 }), "yyyy-MM-dd");

  return (
    <div className="max-w-screen-2xl mx-auto px-4 sm:px-6 py-6">
      {/* Header */}
      <div className="mb-6 flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold" style={{ color: "var(--navy)" }}>Market Overview</h1>
          <p className="text-sm mt-0.5" style={{ color: "var(--text-muted)" }}>
            {data?.latestDate
              ? `Latest trading date: ${new Date(data.latestDate).toLocaleDateString("en-PK", { weekday: "long", year: "numeric", month: "long", day: "numeric" })}`
              : "No trading data available"}
            {" · "}
            <span style={{ color: "#92400E", fontWeight: 600 }}>Demo Data</span>
          </p>
        </div>
        <div className="flex gap-2">
          <Link
            href="/data-portal/daily"
            className="px-4 py-2 rounded-lg text-sm font-medium border transition-colors"
            style={{ borderColor: "var(--navy)", color: "var(--navy)" }}
          >
            Daily View
          </Link>
          <Link
            href="/data-portal/weekly"
            className="px-4 py-2 rounded-lg text-sm font-medium transition-colors"
            style={{ background: "var(--gold)", color: "var(--navy)" }}
          >
            Weekly View
          </Link>
        </div>
      </div>

      {!data ? (
        <div className="card p-8 text-center" style={{ color: "var(--text-muted)" }}>
          <p className="text-lg font-medium">No market data available</p>
          <p className="text-sm mt-2">Run <code>pnpm db:seed && pnpm aggregate:weekly</code> to load demo data.</p>
        </div>
      ) : (
        <>
          {/* Index cards */}
          <div className="grid grid-cols-2 lg:grid-cols-4 gap-4 mb-6">
            {data.indexData.length > 0 ? (
              data.indexData.slice(0, 4).map((idx) => {
                const pct = formatPct(idx.percentageChange);
                return (
                  <StatCard
                    key={idx.indexCode}
                    label={idx.indexCode}
                    value={formatNumber(idx.close, 2)}
                    subValue={pct.text}
                    trend={pct.positive === true ? "up" : pct.positive === false ? "down" : "neutral"}
                  />
                );
              })
            ) : (
              [{ label: "KSE-100", v: "78,432.10" }, { label: "KSE-30", v: "48,628.10" }, { label: "KMI-30", v: "45,490.70" }, { label: "All Share", v: "74,510.50" }].map(i => (
                <StatCard key={i.label} label={i.label} value={i.v} subValue="No data" trend="neutral" />
              ))
            )}
          </div>

          {/* Main grid */}
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
            {/* Left column */}
            <div className="lg:col-span-2 space-y-6">
              {/* Top Gainers */}
              <div className="card">
                <div className="px-5 py-3 border-b flex items-center justify-between" style={{ borderColor: "var(--border)" }}>
                  <h2 className="text-sm font-semibold" style={{ color: "var(--navy)" }}>Top Gainers</h2>
                  <Link href="/data-portal/daily?view=performers&sort=pct_asc" className="text-xs" style={{ color: "var(--gold)" }}>View all →</Link>
                </div>
                <div className="divide-y" style={{ borderColor: "var(--border)" }}>
                  {data.gainers.map((g) => {
                    const pct = formatPct(g.percentageChange);
                    return (
                      <div key={g.symbol} className="px-5 py-3 flex items-center justify-between">
                        <div>
                          <Link href={`/data-portal/company/${g.symbol}`} className="font-semibold text-sm hover:underline" style={{ color: "var(--navy)" }}>{g.symbol}</Link>
                        </div>
                        <div className="text-right">
                          <div className="font-medium text-sm">{formatNumber(g.close)}</div>
                          <div className="text-xs font-semibold" style={{ color: "var(--positive)" }}>{pct.text}</div>
                        </div>
                      </div>
                    );
                  })}
                  {data.gainers.length === 0 && <p className="px-5 py-4 text-sm" style={{ color: "var(--text-muted)" }}>No data for this date.</p>}
                </div>
              </div>

              {/* Top Losers */}
              <div className="card">
                <div className="px-5 py-3 border-b flex items-center justify-between" style={{ borderColor: "var(--border)" }}>
                  <h2 className="text-sm font-semibold" style={{ color: "var(--navy)" }}>Top Losers</h2>
                  <Link href="/data-portal/daily?view=performers" className="text-xs" style={{ color: "var(--gold)" }}>View all →</Link>
                </div>
                <div className="divide-y" style={{ borderColor: "var(--border)" }}>
                  {data.losers.map((g) => {
                    const pct = formatPct(g.percentageChange);
                    return (
                      <div key={g.symbol} className="px-5 py-3 flex items-center justify-between">
                        <div>
                          <Link href={`/data-portal/company/${g.symbol}`} className="font-semibold text-sm hover:underline" style={{ color: "var(--navy)" }}>{g.symbol}</Link>
                        </div>
                        <div className="text-right">
                          <div className="font-medium text-sm">{formatNumber(g.close)}</div>
                          <div className="text-xs font-semibold" style={{ color: "var(--negative)" }}>{pct.text}</div>
                        </div>
                      </div>
                    );
                  })}
                  {data.losers.length === 0 && <p className="px-5 py-4 text-sm" style={{ color: "var(--text-muted)" }}>No data for this date.</p>}
                </div>
              </div>

              {/* Volume Leaders */}
              <div className="card">
                <div className="px-5 py-3 border-b flex items-center justify-between" style={{ borderColor: "var(--border)" }}>
                  <h2 className="text-sm font-semibold" style={{ color: "var(--navy)" }}>Volume Leaders</h2>
                  <Link href="/data-portal/daily?sortBy=volume&sortDir=desc" className="text-xs" style={{ color: "var(--gold)" }}>View all →</Link>
                </div>
                <div className="divide-y" style={{ borderColor: "var(--border)" }}>
                  {data.volumeLeaders.map((g) => (
                    <div key={g.symbol} className="px-5 py-3 flex items-center justify-between">
                      <Link href={`/data-portal/company/${g.symbol}`} className="font-semibold text-sm hover:underline" style={{ color: "var(--navy)" }}>{g.symbol}</Link>
                      <div className="text-right">
                        <div className="font-medium text-sm">{formatVolume(g.volume)}</div>
                        <div className="text-xs" style={{ color: "var(--text-muted)" }}>PKR {formatNumber(g.close)}</div>
                      </div>
                    </div>
                  ))}
                  {data.volumeLeaders.length === 0 && <p className="px-5 py-4 text-sm" style={{ color: "var(--text-muted)" }}>No data for this date.</p>}
                </div>
              </div>
            </div>

            {/* Right column */}
            <div className="space-y-6">
              {/* Quick links */}
              <div className="card p-4">
                <h2 className="text-sm font-semibold mb-3" style={{ color: "var(--navy)" }}>Quick Links</h2>
                <div className="space-y-2">
                  {[
                    { label: "Daily Market Data", href: "/data-portal/daily" },
                    { label: "Weekly Market Data", href: "/data-portal/weekly" },
                    { label: "Market Indices", href: "/data-portal/indices" },
                    { label: "Sector Summary", href: "/data-portal/sectors" },
                    { label: "Company Directory", href: "/data-portal/companies" },
                    { label: "Stock Screener", href: "/data-portal/screener" },
                    { label: "Historical Data", href: "/data-portal/historical-data" },
                    { label: "Research Reports", href: "/data-portal/research" },
                    { label: "Data Downloads", href: "/data-portal/downloads" },
                  ].map((link) => (
                    <Link
                      key={link.href}
                      href={link.href}
                      className="flex items-center justify-between py-2 border-b text-sm transition-colors hover:opacity-70"
                      style={{ borderColor: "var(--border)", color: "var(--text-secondary)" }}
                    >
                      {link.label}
                      <span style={{ color: "var(--gold)" }}>→</span>
                    </Link>
                  ))}
                </div>
              </div>

              {/* Announcements */}
              <div className="card">
                <div className="px-5 py-3 border-b flex items-center justify-between" style={{ borderColor: "var(--border)" }}>
                  <h2 className="text-sm font-semibold" style={{ color: "var(--navy)" }}>Latest Announcements</h2>
                  <Link href="/data-portal/announcements" className="text-xs" style={{ color: "var(--gold)" }}>View all →</Link>
