                          {a.symbol}
                        </span>
                        <div>
                          <p className="text-xs font-medium leading-snug" style={{ color: "var(--text-primary)" }}>{a.title}</p>
                          <p className="text-xs mt-0.5" style={{ color: "var(--text-muted)" }}>{a.announcementDate}</p>
                        </div>
                      </div>
                    </div>
                  ))}
                  {data.announcements.length === 0 && <p className="px-4 py-3 text-sm" style={{ color: "var(--text-muted)" }}>No announcements.</p>}
                </div>
              </div>

              {/* Research */}
              <div className="card">
                <div className="px-5 py-3 border-b flex items-center justify-between" style={{ borderColor: "var(--border)" }}>
                  <h2 className="text-sm font-semibold" style={{ color: "var(--navy)" }}>Research Reports</h2>
                  <Link href="/data-portal/research" className="text-xs" style={{ color: "var(--gold)" }}>View all →</Link>
                </div>
                <div className="divide-y" style={{ borderColor: "var(--border)" }}>
                  {data.research.map((r) => (
                    <div key={r.id} className="px-4 py-3">
                      <p className="text-xs font-medium leading-snug" style={{ color: "var(--text-primary)" }}>{r.title}</p>
                      <p className="text-xs mt-0.5" style={{ color: "var(--text-muted)" }}>{r.publicationDate} · {r.author}</p>
                    </div>
                  ))}
                  {data.research.length === 0 && <p className="px-4 py-3 text-sm" style={{ color: "var(--text-muted)" }}>No reports.</p>}
                </div>
              </div>
            </div>
          </div>
        </>
      )}
    </div>
  );
}

