      db.select({ symbol: dailyStockPrices.symbol, close: dailyStockPrices.close, percentageChange: dailyStockPrices.percentageChange, priceChange: dailyStockPrices.priceChange })
        .from(dailyStockPrices).where(eq(dailyStockPrices.tradingDate, latestDate)).orderBy(asc(dailyStockPrices.percentageChange)).limit(5),
      db.select({ symbol: dailyStockPrices.symbol, volume: dailyStockPrices.volume, close: dailyStockPrices.close })
        .from(dailyStockPrices).where(eq(dailyStockPrices.tradingDate, latestDate)).orderBy(desc(dailyStockPrices.volume)).limit(5),
      db.select().from(companyAnnouncements).where(eq(companyAnnouncements.isPublic, true)).orderBy(desc(companyAnnouncements.announcementDate)).limit(5),
      db.select().from(researchReports).where(eq(researchReports.isPublic, true)).orderBy(desc(researchReports.publicationDate)).limit(3),
    ]);

    return { latestDate, indexData, gainers, losers, volumeLeaders, announcements, research };
  } catch {
    return null;
  }
}

export default async function DataPortalPage() {
